/* ---- 75-comforts.js ---- */
/* ===== From the Machinedrum Editor (2026-10, MM-PORT-PLAN.md a-c): Alt as the global "all", the key map's
   track and transport keys, the home-row keyboard, and the small comforts. On the Monomachine every edit here
   is a change of the view's own state followed by its intent (edit(), the Machinedrum's ops: clearPattern,
   clearLocks, rotate, doublePattern, lock, pasteSteps, steps): one gesture is one undo step (a commit ends it). ===== */

/* ---- Alt, a global modifier: Alt + CLR (or Alt + Delete in Sequence) clears the whole pattern, Alt + the lock
   lane's clear key every lock of the selected track. While Alt is held the keys it changes say so. ---- */
S.alt=false;
function altLabels(){const c=$('[data-sec="clear"]');if(c){c.textContent=S.alt?"All":"Clr";c.title=S.alt?`Clear the whole pattern ${patName(S.pat)}: every track's notes, slides and locks (one undo step)`:"Clear (Delete). Alt: the whole pattern"}
 const cl=$("#clearLane");if(cl){const t=S.alt?`Clear every lock of ${tLabel(S.sel)}`:`Clear ${pidLabel(S.sel,S.lane)} locks. Alt: every lock of ${tLabel(S.sel)}`;cl.title=t;cl.setAttribute("aria-label",t)}}
function showAlt(on){if(S.alt===on)return;S.alt=on;document.body.classList.toggle("althold",on);altLabels();if(S.gen&&S.ws==="seq")genDraw();if(S.gen&&S.ws==="sound")renderMutStrip()}
addEventListener("keydown",e=>showAlt(e.altKey),true);addEventListener("keyup",e=>showAlt(e.altKey),true);addEventListener("blur",()=>showAlt(false));
document.addEventListener("pointermove",e=>showAlt(e.altKey),{passive:true,capture:true});
function clearPattern(){[...S.tracks,...S.midi].forEach(tr=>{tr.steps=tr.steps.map(()=>null);tr.slide=new Set()});S.locks.clear();edit("clearPattern",{});render();toast(`Cleared ${patName(S.pat)}: every track's notes, slides and locks.`)}
function clearTrackLocks(t){const n=trackLockPids(t).length;[...S.locks.keys()].forEach(k=>{if(+k.split("|")[0]===t)S.locks.delete(k)});if(!n){toast(tLabel(t)+" has no locks.");return}edit("clearLocks",{t});render();toast(`Cleared every lock of ${tLabel(t)} (${n} parameter${n>1?"s":""}).`)}

/* ---- the lock budget over the lock lane: the machine's 62 locked parameters in a pattern, pooled over all
   twelve tracks (manual 1-58), as the LCD's meter (dark from 52, blinking at 62) ---- */
function syncLockBudget(){const el=$("#lockbudget");if(!el)return;const n=S.locks.size;el.className="lockbudget"+(n>=62?" full":n>=52?" warn":"");el.innerHTML=`<b>${n}</b> / 62 locked parameters`;
 el.title=`The Monomachine holds 62 locked parameters in a pattern, over all twelve tracks (a track and a parameter with any lock counts once). ${n} in use, ${62-n} left.${n>=62?" Clear a lane before you lock a new parameter.":""}`}

/* ---- rotate: Alt + Left / Right (FUNCTION + arrows on the machine) moves the selected track's steps, slides
   and locks one step, wrapping at the length; swing stays on its steps (the groove, not the notes). The presses
   while Alt stays down are one undo step (rotHold holds the commit). ---- */
let rotHold=false;
addEventListener("keyup",e=>{if(e.key==="Alt")rotHold=false},true);addEventListener("blur",()=>{rotHold=false});
const seqKeys=()=>S.ws==="seq"&&!dialogOpen()&&$("#keyspop").hidden;
const rotStep=(s,by,len)=>((s+by)%len+len)%len;
function rotateTrack(by){const t=S.sel,tr=trk(t),len=S.len;if(len<2)return;
 const st=tr.steps.slice(0,len),sl=new Set();for(let s=0;s<len;s++){tr.steps[rotStep(s,by,len)]=st[s];if(tr.slide.has(s))sl.add(rotStep(s,by,len))}
 for(const s of tr.slide)if(s>=len)sl.add(s);tr.slide=sl;
 for(const[k,m] of S.locks){if(+k.split("|")[0]!==t)continue;const n=new Map();for(const[s,v] of m)n.set(s<len?rotStep(s,by,len):s,v);S.locks.set(k,n)}
 rotHold=true;edit("rotate",{t,by});rerenderSeq()}

/* ---- every-N fill: ⌘-click a step in the roll, every 2nd step from there to the end gets a note at that pitch
   (⌘⇧: every 4th); from a step with a note they go off, with their locks. A NOTE OFF is left alone. ---- */
function fillEvery(t,s,n,pitch){const tr=trk(t),end=S.len,on=!(tr.steps[s]&&!tr.steps[s].off);let ch=0;
 for(let k=s;k<end;k+=n){const st=tr.steps[k];if(st?.off)continue;if(on&&!st){tr.steps[k]=note(pitch);ch++}else if(!on&&st){tr.steps[k]=null;tr.slide.delete(k);clearStepLocks(t,k);ch++}}
 const nth=n===2?"2nd":"4th";if(!ch){toast(`${tLabel(t)} already has every ${nth} step ${on?"on":"off"} from step ${s+1}.`);return}
 edit("steps",{from:s,to:end,rows:[rangeRow(t,s,end)]});renderTop();rerenderSeq();toast(`${on?"Filled every":"Cleared every"} ${nth} step of ${tLabel(t)}, steps ${s+1}–${end}${on?" with "+noteName(pitch):""}.`)}

/* ---- the wheel over a lock-lane step with a trig moves its lock in the lane's parameter (from the kit value when
   it has none): 4 a notch (1 on a short list), ⇧ 1. A run of notches on one step is one undo step. The roll's own
   wheel stays the pitch scroll. ---- */
let wheelLock=null;
$("#main").addEventListener("wheel",e=>{const el=e.target.closest("#lane .lb");if(!el||S.ws!=="seq")return;const t=S.sel,s=+el.dataset.s,st=trk(t).steps[s],d=e.deltaY||(e.shiftKey?e.deltaX:0);
 if(!d||!st||st.off)return;e.preventDefault();const[pg,i]=S.lane.split("."),m=meta(t,pg,+i),mx=maxOf(m),now=performance.now(),key=t+"|"+S.lane+"|"+s;
 if(!wheelLock||wheelLock.key!==key||now-wheelLock.at>700){commit();wheelLock={key}}wheelLock.at=now;
 const had=S.locks.get(lkKey(t,S.lane))?.get(s),cur=had??getP(t,S.lane)??0,v=clamp(cur+(d<0?1:-1)*(e.shiftKey||mx<16?1:4),0,mx);if(had!=null&&v===had)return;
 if(!setLock(t,S.lane,s,v))return;edit("lock",{t,...pidArgs(S.lane),s,v});renderTop();renderLane();toast(`${pidLabel(t,S.lane)} ${fmt(m,v)} · ${tLabel(t)}, step ${s+1}`)},{passive:false});

/* ---- a ramp in the lock lane: ⇧-drag draws a straight line from the press to the pointer, shown as it moves; at
   the release every step with a trig under it is locked on the line, one gesture. ---- */
function lanePoint(e){const cells=$$("#lane .lb");if(!cells.length)return null;const el=cells.find(c=>e.clientX<c.getBoundingClientRect().right)||cells[cells.length-1],r=el.getBoundingClientRect(),{mx}=laneMeta();
 return{s:+el.dataset.s,v:clamp(Math.round((r.bottom-6-e.clientY)/(r.height-14)*mx),0,mx)}}
function rampPoints(){const d=laneDraw,tr=trk(S.sel);if(!d||!d.from)return[];const{mx}=laneMeta(),a=Math.min(d.from.s,d.to.s),b=Math.max(d.from.s,d.to.s),out=[];
 for(let s=a;s<=b;s++){const st=tr.steps[s];if(!st||st.off)continue;const v=d.to.s===d.from.s?d.to.v:d.from.v+(d.to.v-d.from.v)*(s-d.from.s)/(d.to.s-d.from.s);out.push([s,clamp(Math.round(v),0,mx)])}return out}
function rampAt(e){const p=lanePoint(e);if(!p)return;if(!laneDraw.from)laneDraw.from=p;laneDraw.to=p;renderLane();
 for(const[s,v] of rampPoints()){const el=document.querySelector(`#lane .lb[data-s="${s}"]`);if(!el)continue;el.querySelector("i")?.remove();el.insertAdjacentHTML("beforeend",barHTML(v));el.classList.add("ramp")}}
function rampSend(){let n=0;for(const[s,v] of rampPoints()){if(!setLock(S.sel,S.lane,s,v,n>0))break;edit("lock",{t:S.sel,...pidArgs(S.lane),s,v});n++}return n>0}

/* ---- double the pattern (LEN ×2 on LCD line 2): length × 2, the new half a copy of every track's steps, slides,
   swing and locks (64 steps is the longest) ---- */
function doublePattern(){const len=S.len;if(len*2>64){toast(`A pattern of ${len} steps cannot double: 64 steps is the longest.`);return}
 [...S.tracks,...S.midi].forEach(tr=>{for(let s=0;s<len;s++){tr.steps[s+len]=tr.steps[s]&&JSON.parse(JSON.stringify(tr.steps[s]));for(const set of[tr.slide,tr.swing])set.has(s)?set.add(s+len):set.delete(s+len)}});
 for(const m of S.locks.values()){for(let s=len;s<2*len;s++)m.delete(s);for(const[s,v] of[...m])if(s<len)m.set(s+len,v)}
 S.len=len*2;edit("doublePattern",{});render();toast(`Doubled ${patName(S.pat)}: ${len} to ${len*2} steps, the new half a copy.`)}

/* ---- paste to many: ⇧-click track headers to mark them, then ⌘V pastes the copied page into each one (from the
   page shown), one gesture. A plain click on a header, or Esc, unmarks them. (S.multi is MULTI TRIG here.) ---- */
S.marks=new Set();
function markToggle(t){S.marks.has(t)?S.marks.delete(t):S.marks.add(t);renderRail();const l=[...S.marks].sort((a,b)=>a-b).map(tLabel).join(" ");toast(S.marks.size?`⌘V pastes into ${l}`:"No tracks marked for paste")}
document.addEventListener("click",e=>{const th=e.target.closest("#rail .th[data-sel]");if(!th||e.target.closest("button,select,.pc,.fader")||S.ws!=="seq")return;
 if(e.shiftKey){e.preventDefault();e.stopImmediatePropagation();markToggle(+th.dataset.sel);return}if(S.marks.size)S.marks.clear()},true);
function pasteToMany(){const[a,b]=vis();if(CLIP?.type!=="page"){toast("Copy a track page first.");return}const ts=[...S.marks].sort((x,y)=>x-y),ok=ts.filter(t=>isMidiT(t)===CLIP.midi);
 ok.forEach(t=>{pastePage(t,a,b);edit("pasteSteps",{t,from:a,to:b})});if(ok.length)render()
 toast((ok.length?`Pasted steps ${a+1}–${b} into ${ok.map(tLabel).join(" ")} (one undo step).`:"")+(ok.length<ts.length?` ${ts.length-ok.length} marked track(s) skipped: pages paste between synth tracks or between MIDI tracks.`:""))}

/* ---- mutes from the keys: M the selected track, Alt+M every track (any audible: mute all; none: unmute all), 0
   unmutes and unsolos every track (also the rail's M/S OFF key). MIDI tracks only where the engine mutes them. ---- */
const muteOk=t=>t<6||!NA.midiMutes;
function mutesChanged(say){tx();if(HOST.mutes)HOST.mutes();render();if(say&&!["seq","sound","mix","perform"].includes(S.ws))toast(say)}
function muteSel(){const t=S.sel;if(!muteOk(t)){toast(NA.midiMutes);return}const tr=trk(t);tr.mute=!tr.mute;mutesChanged(`${tr.mute?"Muted":"Unmuted"} ${tLabel(t)}`)}
function muteAllToggle(){const ts=[...Array(12).keys()].filter(muteOk),on=ts.some(t=>!trk(t).mute);ts.forEach(t=>trk(t).mute=on);mutesChanged();toast(on?"Every track muted (Alt+M again: unmute all)":"Every track unmuted")}
function unmuteAll(){const ts=[...Array(12).keys()];if(!ts.some(t=>trk(t).solo||(trk(t).mute&&muteOk(t)))){toast("No track is muted or soloed.");return}ts.forEach(t=>{trk(t).solo=false;if(muteOk(t))trk(t).mute=false});mutesChanged();toast("Every track unmuted and unsoloed")}
document.addEventListener("click",e=>{if(e.target.closest("#allon"))unmuteAll()});

/* ---- tap tempo (manual p.36's TAP): the average of the last taps; live recording: RECORD + PLAY ---- */
const TAP=[];
function tapTempo(){const now=performance.now();if(TAP.length&&now-TAP[TAP.length-1]>2000)TAP.length=0;TAP.push(now);if(TAP.length>5)TAP.shift();
 if(TAP.length<2){toast("Tap tempo: keep tapping T");return}S.bpm=clamp(Math.round(60000/((TAP[TAP.length-1]-TAP[0])/(TAP.length-1))*10)/10,30,300);if(HOST.tempo)HOST.tempo(S.bpm);renderTop();if(S.playing)restartClock();toast("Tap tempo: "+S.bpm.toFixed(1)+" BPM")}
function liveRecord(){if(HOST.record)return HOST.record(true);S.rec=!S.rec;if(S.rec&&!S.playing)togglePlay();renderTop();if(S.rec)toast("LIVE RECORDING: the notes you play are recorded.")}

/* ---- the keyboard: the home row plays the selected synth track, from any workspace. A S D F G H J K L are white
   keys C D E F G A B C D from C-3 (Z / X: the octave, −3 to +3), real MIDI notes on the track's own channel
   (GLOBAL › MIDI › CHANNELS: base + track), at KB.vel (C / V: 20 40 60 80 100 127; the machine hears it through
   ASSIGN › VEL). Each key is its own note on and off, so legato and the machine's note priority work as on a
   keyboard; while LIVE RECORDING the machine records them. MIDI tracks are not played (their notes go to the
   MIDI OUT only). Key repeat is ignored. ---- */
const KEYS_WHITE="ASDFGHJKL",KEYS_SEMIS=[0,2,4,5,7,9,11,12,14],KEYS_OCT=[-3,3],KEYS_VELS=[20,40,60,80,100,127],KEYS_BASE=48;
const KB={oct:0,vel:100,held:new Map(),told:new Set()};
function keyVel(v,d){const up=KEYS_VELS.find(x=>x>v),down=[...KEYS_VELS].reverse().find(x=>x<v);return d>0?up??KEYS_VELS[KEYS_VELS.length-1]:down??KEYS_VELS[0]}
/* the keys that play and act on tracks: no dialog or panel open, no text field focused (the one rule of both editors, deskKeys.js) */
function kbOn(){return Keys.free()}
function kbTell(k,t){if(KB.told.has(k))return;KB.told.add(k);toast(t)}
function homeDown(e){if(e.repeat||KB.held.has(e.code))return;const t=S.sel,k=KEYS_WHITE.indexOf(e.code.replace(/^Key/,""));if(k<0)return;
 if(isMidiT(t)){kbTell("midi","The keys play the synth tracks: a MIDI track's notes go to the MIDI OUT only.");return}
 const n=clamp(KEYS_BASE+12*KB.oct+KEYS_SEMIS[k]);KB.held.set(e.code,{t,n});keyNote(t,n,KB.vel)}
function homeUp(code){const h=KB.held.get(code);if(!h)return;KB.held.delete(code);keyNote(h.t,h.n,0)}
/* a host plays the machine (the note intent: pitch in semitones from KEYS_BASE, C3); the example only shows the track's lamp */
function keyNote(t,n,vel){if(HOST.noteOn){const p=n-KEYS_BASE;return vel?HOST.noteOn(t,p,vel):HOST.noteOff(t,p)}if(vel){flashTracks([t]);kbTell("eg","Example: in the plug-in the keys play the machine.")}}
function kbVel(d){KB.vel=keyVel(KB.vel,d);toast(`Keyboard velocity ${KB.vel}`)}
function kbOct(d){KB.oct=clamp(KB.oct+d,KEYS_OCT[0],KEYS_OCT[1]);toast(`Keyboard octave ${KB.oct>0?"+":""}${KB.oct}: A plays ${noteName(KEYS_BASE+12*KB.oct)}`)}
document.addEventListener("keyup",e=>homeUp(e.code));addEventListener("blur",()=>[...KB.held.keys()].forEach(homeUp));
Keys.bind({keys:[...KEYS_WHITE],group:"Playing",hidden:true,field:true,when:kbOn,run:homeDown,does:""});
Keys.bind({keys:["Z"],group:"Playing",hidden:true,field:true,when:kbOn,run:()=>kbOct(-1),does:""});
Keys.bind({keys:["X"],group:"Playing",hidden:true,field:true,when:kbOn,run:()=>kbOct(1),does:""});
Keys.bind({keys:["C"],group:"Playing",hidden:true,field:true,when:kbOn,run:()=>kbVel(-1),does:""});
Keys.bind({keys:["V"],group:"Playing",hidden:true,field:true,when:kbOn,run:()=>kbVel(1),does:""});
Keys.bind({keys:["A S D F G H J K L"],group:"Playing",does:"Play the selected synth track: white keys C D E F G A B C D, real notes on its MIDI channel, from any workspace. While live recording the machine records them"});
Keys.bind({keys:["Z","X"],group:"Playing",does:()=>`Octave down / up, −3 to +3 (now ${KB.oct>0?"+":""}${KB.oct}: A is ${noteName(KEYS_BASE+12*KB.oct)})`});
Keys.bind({keys:["C","V"],group:"Playing",does:()=>`Velocity down / up: 20 40 60 80 100 127 (now ${KB.vel})`});

/* ---- the selected track's keys, the all keys, the step gestures ---- */
Keys.bind({keys:["M"],code:"KeyM",group:"Selected track",does:"Mute or unmute the selected track",when:kbOn,run:()=>muteSel()});
Keys.bind({keys:["M"],code:"KeyM",mod:"alt",group:"All",does:"Mute every track; when none is audible, unmute every track",when:kbOn,run:()=>muteAllToggle()});
Keys.bind({keys:["ArrowUp","ArrowDown"],group:"Selected track",does:"Select the previous / next track of the side shown (a focused value keeps ↑ / ↓ for itself)",
 when:()=>kbOn()&&$("#kpop").hidden&&S.ws!=="song",run:e=>{const sd=side(),i=sd.indexOf(S.sel);select(sd[((i<0?0:i)+(e.key==="ArrowDown"?1:5))%6])}});
Keys.bind({keys:["T"],group:"Transport",does:"Tap tempo (the average of the last taps)",when:kbOn,run:()=>tapTempo()});
Keys.bind({keys:["ArrowLeft","ArrowRight"],mod:"alt",group:"Selected track",does:"Sequence: rotate the selected track one step earlier / later: notes, slides and locks, wrapping at the length. Presses while ⌥ is down are one undo step. The one Alt that is not \"all\": FUNCTION + arrows on the machine",when:seqKeys,run:e=>rotateTrack(e.key==="ArrowRight"?1:-1)});
Keys.bind({keys:["0"],group:"All",does:"Unmute and unsolo every track",when:kbOn,run:()=>unmuteAll()});
Keys.bind({keys:["Escape"],group:"Sequence",does:"Unmark the tracks marked for paste",when:()=>seqKeys()&&S.marks.size>0,run:()=>{S.marks.clear();renderRail()}});
Keys.bind({keys:["roll"],mod:"cmd",group:"Sequence",does:"Click: every 2nd step from there to the end gets a note at that pitch (from a note: off), one undo step"});
Keys.bind({keys:["roll"],mod:"cmd+shift",group:"Sequence",does:"Click: every 4th step from there to the end"});
Keys.bind({keys:["wheel on a lock step"],group:"Sequence",does:"Move its lock in the lane's parameter, 4 a notch (⇧: 1)"});
Keys.bind({keys:["lock lane"],mod:"shift",group:"Sequence",does:"Drag: a ramp, a straight line from the press to the release (one undo step)"});
Keys.bind({keys:["track header"],mod:"shift",group:"Sequence",does:"Click: mark the track for paste; ⌘V then pastes into every marked track (one undo step)"});

/* ---- 76-gen.js ---- */

/* ===== GEN and MUTATE on the page (MM-PORT-PLAN.md d, the Machinedrum Editor's DESIGN-generators.md §5) =====
   The GEN bar, always under the piano roll on Sequence (it holds the PAGE control too), and the MUTATE bar, always
   over the Sound pages. Both are live: a change writes at once. A run of changes in one context (the workspace,
   the selected track, the pattern or the kit) is one gesture, one undo step: the commits after each click wait
   (genHeld, like rotate's rotHold) until the run ends, on another context, any other edit, undo or redo. Each change
   generates from the run's base, the pattern before it, so a value moved back gives its steps back. The results
   come from the pure functions (skins/shared/deskGen.js, 52-gen.js); here they become the view's own state, and
   GEN's are the steps intent of the tracks it wrote (their steps, slides and locks over the range, so a value moved
   back gives its steps back); MUTATE's are the params intent of the values it moved. Alt is the global "all": Alt + a GEN change
   every track of the side shown over the whole pattern, Alt+R every track (Sound: every synth track). ===== */
S.gen={specs:null,last:[],m:[],run:null};
S.mut={amount:20,seed:genSeed(),scope:new Set(["SYN"]),trial:null,note:""};
S.genOwn=false;
const genKey=()=>`${S.ws}:${S.sel}:${S.pat}`,mutKey=()=>`${S.ws}:${S.sel}:${S.kit}`;
function genInfo(t){const tr=trk(t);return{m:tr.m,notes:tr.steps.slice(0,S.len).flatMap(x=>x&&!x.off&&x.n||[]),key:tr.tr?.KEY|0,scale:tr.tr?.SCALE|0}}
/* every track's spec: from its role the first time, again when its machine changed and the spec was never edited */
function genSpecs(fill){const len=S.len||64;
 if(!S.gen.specs||fill){S.gen.specs=[];S.gen.last=[];S.gen.m=[]}
 for(let t=0;t<12;t++){const m=trk(t).m;if(!S.gen.specs[t]||(S.gen.m[t]!==m&&!S.gen.last[t]?.edited)){S.gen.specs[t]=mmGenDefault(genInfo(t),len,isMidiT(t));S.gen.m[t]=m;S.gen.last[t]={}}
  S.gen.specs[t]=genFit(S.gen.specs[t],len)}	/* STEPS never longer than the pattern, also when it got shorter */
 return S.gen.specs}
function genSpec(t=S.sel){return genSpecs()[t]}
const genEdited=(t=S.sel)=>{S.gen.last[t].edited=true};
/* the range a generator writes: the steps shown, Alt the whole pattern */
function genRange(all){const[a,b]=vis();return all?[0,S.len]:[a,Math.min(b,S.len)]}
/* a run or a trial with changes in the context shown holds the commits: one undo step */
function genHeld(){return !!(S.gen&&((S.gen.run?.applied&&S.gen.run.key===genKey())||(S.mut.trial?.applied&&S.mut.trial.key===mutKey())))}
/* the run or the trial ends: its gesture closes (the next edit is a new undo step) */
function genEnd(){if(!S.gen)return;const r=S.gen.run,m=S.mut.trial,live=(r&&r.applied)||(m&&m.applied);S.gen.run=null;S.mut.trial=null;S.mut.note="";if(!live)return;
 S.genEnding=true;try{if(HOST.commit)HOST.commit()}finally{S.genEnding=false}}
function genStale(){if(S.gen&&((S.gen.run&&S.gen.run.key!==genKey())||(S.mut.trial&&S.mut.trial.key!==mutKey())))genEnd()}
/* a run's base: every track's steps, slides and locks before the run */
function genBase(){return[...Array(12).keys()].map(t=>{const tr=trk(t);return{steps:tr.steps.map(x=>x&&JSON.parse(JSON.stringify(x))),slide:new Set(tr.slide),
 locks:[...S.locks].filter(([k])=>+k.split("|")[0]===t).map(([k,m])=>[k.split("|")[1],new Map(m)])}})}
function genStart(key){if(S.gen.run&&S.gen.run.key===key)return;genEnd();commit()}
/* one track over [from, to): back to the run's base there, then the generated steps; the trigs it turns off lose
   their locks and slides. False: the track is set to keep (and nothing of a run to give back). */
function genWrite(t,from,to,run){const b=run.base[t],tr=trk(t),r=mmGenSteps(genSpec(t),t,from,to,b.steps,S.len,isMidiT(t));
 if(!r&&!run.applied)return false;
 for(let s=from;s<to;s++){tr.steps[s]=b.steps[s]&&JSON.parse(JSON.stringify(b.steps[s]));b.slide.has(s)?tr.slide.add(s):tr.slide.delete(s);clearStepLocks(t,s);for(const[pid,m] of b.locks)if(m.has(s))setLock(t,pid,s,m.get(s),true)}
 if(!r)return true;
 for(const[s,st] of r.steps)tr.steps[s]=st;
 for(const s of r.gone){clearStepLocks(t,s);tr.slide.delete(s)}
 return true}
/* Live: every change of a GEN control writes at once (all: every track of the side shown, the whole pattern) */
function genLive(all=S.alt){
 if(S.rec){toast("The generators wait while the machine records live.");return false}
 genStale();genStart(genKey());
 const run=genRunFor(S.gen.run,genKey(),genBase,()=>0),[from,to]=genRange(all),wrote=[];
 for(const t of all?side():[S.sel])if(genWrite(t,from,to,run))wrote.push(t);
 if(!wrote.length){toast(all?"Every track is set to keep: nothing to generate.":`${tLabel(S.sel)} is set to keep.`);genDraw();return false}
 S.gen.run=run;run.applied++;
 S.genOwn=true;try{edit("steps",{from,to,rows:wrote.map(t=>rangeRow(t,from,to,true))})}finally{S.genOwn=false}
 autoRange(S.sel);if(S.ws==="seq")rerenderSeq();else renderTop();
 return true}
/* the result of a track's spec for the summary: its trigs over the range from the run's base (or now) */
function genPreview(t,from,to){const run=S.gen.run&&S.gen.run.key===genKey()?S.gen.run:null,base=run?run.base[t].steps:trk(t).steps;
 return{run,base,r:mmGenSteps(genSpec(t),t,from,to,base,S.len,isMidiT(t))}}
/* Defaults (↺): every spec from its machine; writes this track (Alt every track) */
function genDefaults(){genSpecs(true);toast("Every track's spec from its machine.");genLive()}
/* a new variation: a new seed (random, the notes), random hits and rotation in the cycle (euclid); keep stays */
function genVary(t){const sp=genSpec(t),r=n=>Math.floor(Math.random()*n);if(sp.kind==="keep")return false;
 sp.seed=genSeed();if(sp.kind==="euclid"){sp.k=1+r(sp.n);sp.rot=r(sp.n)}S.gen.last[t].edited=true;return true}
function genAgain(all=false){const ts=all?side():[S.sel],varied=ts.filter(genVary).length;
 if(!varied){toast(all?"Every track is set to keep: nothing to randomise.":`${tLabel(S.sel)} is set to keep: nothing to randomise.`);return}
 if(genLive(all)&&S.ws!=="seq")toast(all?"GEN: a new variation of every track.":`GEN: a new variation of ${tLabel(S.sel)}.`)}
/* the one randomise action (R; Alt+R or Alt-click on the R key: all), by workspace */
function randomise(all){if(S.ws==="sound")mutAgain(all);else genAgain(all)}
function genKind(kind){const t=S.sel,sp=genSpec(t),last=S.gen.last[t];if(sp.kind===kind)return;last[sp.kind]=sp;last.edited=true;
 const notes=sp.notes&&JSON.parse(JSON.stringify(sp.notes)),seed=sp.seed||genSeed();
 S.gen.specs[t]=genFit(last[kind],S.len||64)||(kind==="euclid"?{kind,k:4,n:Math.min(16,S.len||64),rot:0,seed,notes}:kind==="random"?{kind,density:25,seed,mode:"replace",notes}:{kind,notes});
 genLive()}
const genCycle=(list,cur,d)=>list[((list.indexOf(cur)+(d>0?1:-1))%list.length+list.length)%list.length];
/* a value of a bar moved by d (wheel, arrows, click, drag), in the spec's own ranges */
function genVal(k,d){const lim=(v,a,b)=>Math.max(a,Math.min(b,v));
 if(k==="amt"){S.mut.amount=lim(S.mut.amount+d,0,100);mutLive();renderMutStrip();return}
 const sp=genSpec(),n=sp.notes;genEdited();
 if(k==="k")sp.k=lim(sp.k+d,0,sp.n);
 if(k==="n"){sp.n=lim(sp.n+d,1,Math.min(64,S.len||64));sp.k=Math.min(sp.k,sp.n);sp.rot=Math.min(sp.rot,sp.n-1)}
 if(k==="rot")sp.rot=((sp.rot+d)%sp.n+sp.n)%sp.n;
 if(k==="dens")sp.density=lim(sp.density+d,0,100);
 if(k==="seed")sp.seed=((sp.seed-1+d)%99999+99999)%99999+1;
 if(n){if(k==="nmot")n.motion=genCycle(n.motion==="kit"||trk(S.sel).m==="DPRO-BBOX"?["off","kit"]:["off","step","leap"],n.motion,d);
  if(n.motion!=="kit"&&n.motion!=="off"&&n.root==null){const i=genInfo(S.sel),x=mmGenDefault({...i,m:"SWAVE-SAW"},S.len);Object.assign(n,x.notes)}
  if(k==="nroot")n.root=lim(n.root+d,0,127-12*n.range);
  if(k==="nscale")n.scale=genCycle(MM_SCALES,n.scale,d);
  if(k==="nrange"){n.range=lim(n.range+(d>0?1:-1),1,2);n.root=Math.min(n.root,127-12*n.range)}}
 genLive()}
/* The bars' pieces (the Machinedrum Editor's): a group (a title on a thin rule over its controls), a value (an LCD
   window, its label inside), a key (a small square cap with its keyboard key on it and a tiny label over it). */
const gbg=(label,body,cls="",tip="")=>`<div class="gbg ${cls}"${tip?` title="${tip}"`:""}><span class="gbl">${label}</span><div class="gbc">${body}</div></div>`;
const gv=(k,label,v,tip)=>`<span class="gv" data-gv="${k}" role="spinbutton" tabindex="0" aria-label="${label}" aria-valuenow="${parseInt(v)||0}" title="${tip}. Drag up or down, scroll, or click (⇧-click: down)."><small>${label}</small><b>${v}</b></span>`;
const gkc=(attr,act,cap,label,tip)=>`<button class="kc" ${attr}="${act}" title="${tip}" aria-label="${label}"><small>${label}</small><kbd>${cap}</kbd></button>`;
const randKey=tip=>`<button class="kc cream krand" data-rand="1" title="${tip}" aria-label="Randomise"><small>Random <em>⌥R all</em></small><kbd>R</kbd></button>`;
const gtitle=(name,target,all,tip)=>`<div class="gbt" title="${tip}"><b>${name}</b><span class="${all?"all":""}">${target}</span></div>`;
const gseg=(attr,cur,items,tips)=>`<span class="seg">${items.map(([k,n])=>`<button ${attr}="${k}" aria-pressed="${cur===k}" title="${tips[k]}">${n}</button>`).join("")}</span>`;
function genNotesHtml(sp,t){const n=sp.notes;if(!n||sp.kind==="keep"||isMidiT(t))return"";const kit=n.motion==="kit"||trk(t).m==="DPRO-BBOX";
 const mot=gv("nmot","Notes",n.motion==="off"?"off":n.motion,kit?"Off: the steps keep their drums (a new one takes the last). KIT: each hit picks BD1, SD1, CH or OH":"Off: the steps keep their pitch (a new one takes the track's last note). STEP: a walk of 1 or 2 scale degrees from the root. LEAP: any note of the range");
 const seed=sp.kind==="euclid"&&n.motion!=="off"?gv("seed","Seed",sp.seed,"The same seed gives the same notes"):"";
 if(n.motion==="off"||n.motion==="kit")return gbg("Notes",mot+seed,"gnotes","The rhythm decides when, the notes what: they go to the hits the rhythm writes");
 return gbg("Notes",mot+gv("nroot","Root",noteName(n.root),"The lowest note: the scale's root at its octave (the track's KEY when its SCALE is MAJ or MIN)")+gv("nscale","Scale",n.scale==="DORIAN"?"DOR":n.scale,"MAJ, MIN, PENT (minor pentatonic) or DORIAN")
  +gv("nrange","Range",n.range+" oct","One or two octaves from the root")+seed,"gnotes","The rhythm decides when, the notes what: they go to the hits the rhythm writes (every hit; in ADD the new ones, in THIN none)")}
function genStripHtml(){const t=S.sel,tr=trk(t),sp=genSpec(t),all=S.alt,[from,to]=genRange(all),{run,base,r}=genPreview(t,from,to);
 const mode=gbg("Mode",gseg("data-genkind",sp.kind,[["euclid","Euclid"],["random","Random"],["keep","Keep"]],{euclid:"k hits spread evenly over n steps, rotated",random:"each step on by chance, from a seed",keep:"leave this track as it is (in a run: as it was before the run)"}),"gmode");
 const params=sp.kind==="euclid"?gbg("Euclid",gv("k","Hits",sp.k,"How many hits in a cycle")+gv("n","Steps",sp.n,"The cycle's length in steps, at most the pattern's; it repeats over the pattern")+gv("rot","Rotate",sp.rot,"Moves the hits later"))
  :sp.kind==="random"?gbg("Random",gv("dens","Density",sp.density+"%","The chance of each step")+gv("seed","Seed",sp.seed,"The same seed gives the same steps"))
   +gbg("Write",gseg("data-genmode",sp.mode,[["replace","Replace"],["add","Add"],["thin","Thin"]],{replace:"the track becomes the result",add:"only steps that are off may turn on",thin:"only steps that are on may turn off"}),"gwrite")
  :gbg("Keep",`<span class="gsum">${tLabel(t)} is left as it is.</span>`);
 let sum="";
 if(r){const on=r.steps.filter(([,st])=>mmTrig(st)).length,b=[];for(let s=from;s<to;s++)if(mmTrig(base[s]))b.push(s);const now=new Set(r.steps.filter(([,st])=>mmTrig(st)).map(([s])=>s));
  const add=[...now].filter(s=>!mmTrig(base[s])).length,gone=b.filter(s=>!now.has(s)).length;
  sum=all?`every track · steps ${from+1}–${to}`:`${sp.kind==="euclid"?genSummary(sp,S.len)+" · ":""}${on} on${run?` <em>+${add} −${gone}</em>`:""} · steps ${from+1}–${to}`}
 else if(all)sum=`every track · steps ${from+1}–${to}`;
 const target=all?`all ${isMidiT(t)?"MIDI":"synth"} tracks`:`${tLabel(t)} · ${isMidiT(t)?"CH"+String(tr.ch).padStart(2,"0"):tr.m.replace("SWAVE-","SW-")}`;
 return`${gtitle("Gen",target,all,"Generators: every change writes to the pattern at once. A run of changes on this track is one undo step; Undo takes it back in one step. Alt: every track of the side shown, the whole pattern.")}
  ${mode}${params}${genNotesHtml(sp,t)}
  <div class="gsum" title="${run&&run.applied?"What the run changed, against the pattern before it":"What a change writes"}">${sum}</div>
  <div class="gkeys">${randKey(all?"Randomise every track of the side: a new variation of each spec, the whole pattern (Alt+R)":`Randomise ${tLabel(t)}: a new variation, ${sp.kind==="random"?"a new seed":sp.kind==="euclid"?"random hits and rotation in the cycle, a new seed for the notes":"nothing while it is set to Keep"} (R). Alt+R or Alt-click: every track`)}${gkc("data-gen","fill","↺","Defaults","Defaults: every track's spec from its machine: a bass 5/16 with a walk in its scale, a lead random 30 % over two octaves, a pad on 1 and 3, the drum box 8/16 on BD SD CH OH; FX machines kept; MIDI tracks 4/16, rhythm only. Writes this track (Alt: every track)")}</div>`}
/* the step gestures behind a small ? key (a click: the list of keys) */
function stepLegend(){const midi=isMidiT(S.sel),row=(cls,what,how)=>`<span>${cls!=null?`<i class="lg on ${cls}"></i>`:`<i class="lg none"></i>`}<b>${what}</b>${how}</span>`;
 return`<span class="steplegend"><button class="glegkey" id="steplegend" aria-label="Step gestures" aria-describedby="steplegpop">?</button><span class="legend glegpop" id="steplegpop" role="tooltip">${row("","Note","click in the roll; drag for pitch")}${midi?"":row("g","Trigless","no envelope trigs (the ENV row)")}${row("y","Note off","alt-click an empty step")}${row("lk","Has locks","a lock on the step")}${row(null,"Fill","⌘-click: every 2nd step from there to the end gets the note (from a note: off); ⌘⇧-click: every 4th")}<small>? the list of keys</small></span></span>`}
function genBarHtml(){return`<div class="genbar"><div class="genband" id="genband">${genStripHtml()}</div><span class="gdiv" aria-hidden="true"></span>${stepLegend()}${pageKeys()}</div>`}
/* a rail tag's tooltip: the spec and its notes */
function genTip(t){const sp=genSpec(t),n=isMidiT(t)?"":mmNotesTag(sp,noteName);return`${genTag(sp)}${n?" · "+n:""}: ${tLabel(t)}'s generator (the GEN bar)`}
/* the bar again (and the rail's spec tags), without a full render */
function genDraw(){if(S.ws!=="seq")return;const host=$("#genband");if(host)host.innerHTML=genStripHtml();$$(".th[data-sel] .gtag").forEach(g=>{g.textContent=genTag(genSpec(+g.closest(".th").dataset.sel))})}

/* ---- MUTATE ---- */
const MUT_SCOPES=[["SYN","Syn","the machine's SYNTHESIS page (an FX machine's INP stays)"],["AMP","Amp","the AMP page (VOL stays)"],["FLT","Flt","the FILTER page"],["EFX","Efx","the EFFECTS page"],["LFO","Lfo","the three LFOs (their PAGE and DEST stay: where an LFO goes is routing)"]];
/* the groups in the scope (a group's title on the Sound page, "SYN:unison", "LF2:lfo"): their knobs on each
   track, by that track's machine (a machine without the group gives none) */
function mutGroupKnobs(tracks,base){const keys=[...S.mut.scope].filter(x=>x.includes(":")),out={};if(!keys.length)return out;
 for(const t of tracks){const g=mmSoundGroups(base[t].m);if(!g)continue;const list=[];
  for(const id of keys){const[pg,key]=id.split(":");if(/^LF\d$/.test(pg)){[2,3,4,5,6,7].forEach(i=>list.push([pg,i]));continue}const x=(g[pg]||[]).find(y=>y.key===key);if(x)x.idx.forEach(i=>list.push([pg,i]))}
  out[t]=list}
 return out}
function mutInfo(t,pg,i){const name=pnames(t,pg)?.[i];return name?{name,max:maxOf(meta(t,pg,i))}:null}
/* one apply of the trial: always from its base (R gives a fresh random sound, it never walks away), one gesture */
function mutApply(all){
 if(!all&&isMidiT(S.sel)){toast("MUTATE moves the synth tracks' sounds: a MIDI track's page is not a sound (Alt+R: every synth track).");return}
 if(!S.mut.scope.size){toast("Pick what to move: SYN, AMP, FLT, EFX or LFO, or a group's title.");return}
 genStale();let tr=S.mut.trial;
 if(!tr||tr.key!==mutKey()){genStart(mutKey());S.mut.seed=genSeed();tr=S.mut.trial={key:mutKey(),base:S.tracks.map(x=>({m:x.m,v:JSON.parse(JSON.stringify(x.v))})),touched:new Set(),all:false,applied:0}}
 tr.all=all;const tracks=all?[0,1,2,3,4,5]:[S.sel];
 const spec={tracks,pages:[...S.mut.scope].filter(x=>!x.includes(":")),extra:mutGroupKnobs(tracks,tr.base),amount:S.mut.amount,seed:S.mut.seed,protect:["VOL","TUNE"]};
 const values=mmMutate(spec,tr.base,mutInfo),now=new Set(values.map(([t,pg,i])=>t+":"+pg+":"+i));
 /* what an earlier apply moved and this one does not goes back to the base */
 for(const k of tr.touched)if(!now.has(k)){const[t,pg,i]=k.split(":");values.push([+t,pg,+i,tr.base[+t].v[pg][+i]])}
 if(!values.length){toast("Nothing to move here: no knobs in that scope.");return}
 for(const[t,pg,i,v] of values){S.tracks[t].v[pg][i]=v;const k=t+":"+pg+":"+i;v!==tr.base[t].v[pg][i]?tr.touched.add(k):tr.touched.delete(k)}
 S.genOwn=true;try{edit("params",{values:values.map(([t,pg,i,v])=>[t,PAGES.indexOf(pg),i,v])})}finally{S.genOwn=false}
 tr.applied++;
 const moved=new Set(values.map(([t])=>t)).size;S.mut.note=`seed ${S.mut.seed} · ${moved} track${moved===1?"":"s"}, ${values.length} values`;
 if(S.ws==="sound")render();else{renderTop();toast(`MUTATE: ${all?"every synth track":tLabel(S.sel)}, ${S.mut.note}.`)}}
/* amount or scope moved during a trial: heard at once, the same seed */
function mutLive(){if(S.mut.trial&&S.mut.trial.key===mutKey()&&S.mut.trial.applied)mutApply(S.mut.trial.all)}
/* R on Sound: a fresh random sound (a new seed) from the trial's base; all: every synth track */
function mutAgain(all=false){S.mut.seed=genSeed();mutApply(all)}
function mutStripHtml(){const t=S.sel,all=S.alt,tr=S.mut.trial&&S.mut.trial.key===mutKey()?S.mut.trial:null,midi=isMidiT(t);
 const chips=MUT_SCOPES.map(([g,n,tip])=>`<button data-mutg="${g}" aria-pressed="${S.mut.scope.has(g)}" title="Every knob of ${tip}">${n}</button>`).join("");
 return`${gtitle("Mutate",all?"every synth track":midi?`${tLabel(t)} · MIDI page`:`${tLabel(t)} · ${trk(t).m.replace("SWAVE-","SW-")}`,all,"Mutate: each knob in scope is pulled toward a random target by the amount, from a seed. A trial is one undo step; Undo takes it back in one step. VOL and TUNE stay. Alt: every synth track.")}
  ${gbg("Move",gv("amt","Amount",S.mut.amount+"%","How far each knob moves toward its random target"))}
  ${gbg("Scope",`<span class="seg">${chips}</span>${(n=>`<span class="ghint">${n?`+ ${n} group${n===1?"":"s"}`:"+ a group's title"}</span>`)([...S.mut.scope].filter(x=>x.includes(":")).length)}`,"gscope","The DATA pages Mutate moves; click a group's title below to add that group")}
  <div class="gsum" title="${S.mut.note}">${S.mut.note||(midi?"A MIDI track has no sound to move: Alt+R moves every synth track.":"")}</div>
  <div class="gkeys">${randKey(`${all?"Randomise every synth track":`Randomise ${tLabel(t)}`}: a fresh random sound, from the sound before the trial${tr?"":" (this sound)"}. One trial is one undo step (R; Alt+R or Alt-click: every synth track)`)}</div>`}
function mutBarHtml(){return`<div class="genband mutband" id="mutband">${mutStripHtml()}</div>`}
function renderMutStrip(){const host=$("#mutband");if(host)host.innerHTML=mutStripHtml();$$("[data-mutsg]").forEach(b=>b.setAttribute("aria-pressed",S.mut.scope.has(b.dataset.mutsg)))}

/* ---- the bars' clicks, values (drag, wheel, arrows) and keys ---- */
document.addEventListener("click",e=>{
 const g=e.target.closest("[data-gen]");if(g&&!g.disabled){if(g.dataset.gen==="fill")genDefaults();return}
 const rk=e.target.closest("[data-rand]");if(rk&&!rk.disabled){randomise(e.altKey||e.metaKey||e.ctrlKey);return}
 const k=e.target.closest("[data-genkind]");if(k){genKind(k.dataset.genkind);return}
 const md=e.target.closest("[data-genmode]");if(md){const sp=genSpec();if(sp.mode!==md.dataset.genmode){sp.mode=md.dataset.genmode;genEdited();genLive()}return}
 const v=e.target.closest(".gv[data-gv]");if(v&&!v.dataset.dragged){genVal(v.dataset.gv,e.shiftKey?-1:1);return}
 const c=e.target.closest("[data-mutg],[data-mutsg]");if(c){const id=c.dataset.mutg||c.dataset.mutsg;S.mut.scope.has(id)?S.mut.scope.delete(id):S.mut.scope.add(id);renderMutStrip();mutLive();e.stopPropagation();return}
 if(e.target.closest("#steplegend")){toggleKeys(true);e.stopPropagation()}},true);
let gvDrag=null;
document.addEventListener("pointerdown",e=>{const v=e.target.closest(".gv[data-gv]");if(!v||e.button!==0)return;gvDrag={v,y:e.clientY,k:v.dataset.gv,acc:0};delete v.dataset.dragged;try{v.setPointerCapture(e.pointerId)}catch(_){}});
document.addEventListener("pointermove",e=>{if(!gvDrag)return;const d=Math.trunc((gvDrag.y-e.clientY)/6)-gvDrag.acc;if(!d)return;
 gvDrag.acc+=d;gvDrag.v.dataset.dragged="1";genVal(gvDrag.k,d*(gvDrag.k==="dens"||gvDrag.k==="amt"?2:1));
 const n=document.querySelector(`.gv[data-gv="${gvDrag.k}"]`);if(n){n.dataset.dragged="1";gvDrag.v=n}});
document.addEventListener("pointerup",()=>{if(!gvDrag)return;const k=gvDrag.k;gvDrag=null;setTimeout(()=>{const n=document.querySelector(`.gv[data-gv="${k}"]`);if(n)delete n.dataset.dragged},0)});
document.addEventListener("wheel",e=>{const v=e.target.closest?.(".gv[data-gv]");if(!v)return;e.preventDefault();genVal(v.dataset.gv,((e.deltaY||e.deltaX)<0?1:-1)*(e.shiftKey?10:1))},{passive:false});
document.addEventListener("keydown",e=>{const v=e.target.closest?.(".gv[data-gv]");if(!v)return;const d={ArrowUp:1,ArrowRight:1,ArrowDown:-1,ArrowLeft:-1}[e.key];if(d==null)return;
 e.preventDefault();e.stopPropagation();const k=v.dataset.gv;genVal(k,d*(e.shiftKey?10:1));document.querySelector(`.gv[data-gv="${k}"]`)?.focus()},true);
Keys.bind({keys:["R"],code:"KeyR",group:"Selected track",when:kbOn,run:()=>randomise(false),
 does:"Randomise the selected track: on Sound a fresh random sound (MUTATE, from the sound before the trial); everywhere else a new GEN variation: a new seed, or random hits and rotation"});
Keys.bind({keys:["R"],code:"KeyR",mod:"alt",group:"All",when:kbOn,run:()=>randomise(true),
 does:"Randomise every track: on Sound every synth track's sound, everywhere else every GEN spec of the side shown over the whole pattern"});
Keys.bind({keys:["GEN value"],mod:"alt",group:"All",does:"Change a GEN value: every track of the side shown, the whole pattern (one undo step per run)"});
Keys.bind({keys:["R key"],mod:"alt",group:"All",does:"Click: randomise every track (Sound: every synth track; VOL and TUNE stay)"});

/* ---- 80-notes.js ---- */

/* ===== Gates, arpeggiator, transpose, trig setup (the dock under the note lane) ===== */
const ARPM=["OFF","KEY","SID","ADD"],ARPP=["TRUE","UP","DOWN","CYCLE","RND"],SCALES=["---","FIX","MAJ","MIN"];
const ARPHELP={0:"<b>OFF</b> The track plays the base note of each trig. Chord notes wait for the arpeggiator or POLY.",
 1:"<b>KEY</b> Runs while notes are held and plays only held notes. Release all and it stops.",
 2:"<b>SID</b> Needs two or more notes. They stay in the cycle after release until a new chord.",
 3:"<b>ADD</b> Starts on the first note. Each extra key joins while one key is held."};
function midiLenSteps(t,s){const v=S.locks.get(lkKey(t,"MID.0"))?.get(s)??trk(t).v.MID[0];return v>=127?Infinity:Math.max(.25,v/8)}
/* a gate runs from a note trig to its NOTE OFF or the next trig (synth tracks), or for LEN (MIDI) */
function noteSpans(t){const tr=trk(t),out=[],L=S.len;
 for(let s=0;s<L;s++){const st=tr.steps[s];if(!st||st.off)continue;let e=s+1;
  if(isMidiT(t)){const d=midiLenSteps(t,s);if(d===Infinity){e=L;for(let k=s+1;k<L;k++)if(tr.steps[k]?.off){e=k;break}}else e=Math.min(L,s+d)}
  else{while(e<L&&!tr.steps[e])e++}
  out.push({s,e,n:st.n?st.n:[lastNote(t,s)],st,kind:stepKind(st),pitchless:!st.n,endOff:!!tr.steps[e]?.off})}return out}
/* honest gate: the amp envelope may die before the gate ends (HOLD, then DEC). Estimate, in steps. */
function ampSteps(t){if(isMidiT(t))return Infinity;const a=trk(t).v.AMP;if(a[2]>=127)return Infinity;return(a[0]+a[1]+a[2])/127*16}
function arpSeq(tr,chord){const a=tr.arp;let c=[...chord];if(a.PLAY===1)c.sort((x,y)=>x-y);if(a.PLAY===2)c.sort((x,y)=>y-x);if(a.PLAY===3){c.sort((x,y)=>x-y);c=[...c,...c.slice(1,-1).reverse()]}
 let seq=[];for(let o=0;o<=a.RNGE;o++)seq=seq.concat(c.map(n=>n+12*o));if(a.PLAY===4){let h=7;seq=seq.map(()=>seq[(h=(h*31+11)%97)%seq.length])}return seq}
function arpTicks(t,span){const tr=trk(t),a=tr.arp;if(!a.MODE||!a.SPD)return[];if(a.MODE===2&&span.n.length<2)return[];const tl=a.SPD/6,seq=arpSeq(tr,span.n),out=[];
 for(let k=0;k*tl<span.e-span.s&&k<256;k++){const r=k%a.len;if(!a.rhy[r])continue;out.push({x:span.s+k*tl,w:tl,n:seq[k%seq.length]+a.ofs[r]})}return out}
/* a lane-style key per arp step: the offset is a bipolar LED meter from the middle line (±24 = the half key) */
function arpCells(a){return Array.from({length:16},(_,k)=>{const o=a.ofs[k],on=a.rhy[k],na=k>=a.len,f=(Math.abs(o)/24).toFixed(4);
 return`<div class="ac ${na?"na":""} ${on?"":"mute"}" data-ac="${k}" title="Step ${k+1}: ${na?"past the end (click to extend)":on?"plays, offset "+(o>0?"+":"")+o:"muted"}. Click = mute, drag = offset.">${na?"":`<span class="z"></span><i class="${o>=0?"up":"dn"}" style="${o>=0?`bottom:50%;height:max(2px,calc((50% - 8px)*${f}))`:`top:50%;height:calc((50% - 8px)*${f})`}"></i><b>${o?(o>0?"+":"")+o:k+1}</b>`}</div>`}).join("")}
/* The dock's tabs share one layout, the lock lane's: the rail's LOCK PARAMETER keys area holds the panel's
   choices as keys (a group label over each row, the lock-parameter key style), the dock body holds one row of
   value boxes on eight fixed columns and the panel's picture under it, down to the lane's bottom line. The
   help is one muted line in the header (the long text in its tooltip). Nothing here sizes the dock. */
const dkk=(attrs,on,txt,title="")=>`<button class="pk dkk" ${attrs} aria-pressed="${!!on}"${title?` title="${title}"`:""}>${txt}</button>`;
const dkGroup=(label,keys,n,attrs="")=>`<div class="dkg"><span class="dkl">${label}</span><div class="dkrow ${n>4?"tight":""}" style="--n:${n}" ${attrs}>${keys}</div></div>`;
const dkAttr=s=>String(s).replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;");
const dkPlain=h=>h.replace(/<b>([^<]*)<\/b>/g,"$1:").replace(/<[^>]+>/g,"");
function dockKeys(t,d){const tr=trk(t),midi=isMidiT(t);
 if(d==="arp"){const a=tr.arp;return dkGroup("Mode",ARPM.map((m,i)=>dkk(`data-v="${i}"`,a.MODE===i,m)).join(""),4,`data-set="arpmode"`)
  +dkGroup("Play",ARPP.map((m,i)=>dkk(`data-v="${i}"`,a.PLAY===i,m)).join(""),5,`data-set="arpplay"`)
  +dkGroup("Trig",midi?`<span class="dkna" title="MIDI arpeggiators have no envelope switches">none on MIDI</span>`:["amp","flt","lfo"].map(k=>dkk(`data-arptrig="${k}"`,a[k],k.toUpperCase(),`The arpeggiator's notes retrigger the ${k.toUpperCase()} envelope`)).join(""),3)}
 if(d==="trn"){const sc=tr.tr.SCALE;return dkGroup("Scale",SCALES.map((m,i)=>dkk(`data-v="${i}"`,sc===i,m)).join(""),4,`data-set="scale"`)
  +`<div class="dkg"><span class="dkl">Key</span><span class="dkna" title="${sc>1?"Click a key on the keyboard to set the root":"KEY only matters for MAJ and MIN"}">${sc>1?KEYS[tr.tr.KEY]+" · click the keyboard":"only for MAJ and MIN"}</span></div>`}
 if(d==="trig"){const tp=tr.trigpos??"";return dkGroup("Trig position",[dkk(`data-v=""`,tp==="","—","No forwarding")].concat([0,1,2,3,4,5].filter(k=>k!==t).map(k=>dkk(`data-v="${k}"`,tp===k,"T"+(k+1),"Also play "+tLabel(k)+" "+S.tracks[k].m))).join(""),6,`data-set="trigpos"`)
  +dkGroup("Port",["ALWAYS","LEGATO"].map((m,i)=>dkk(`data-v="${i}"`,tr.port===i,m,i?"ONLY LEGATO: glide only between overlapping notes":"Glide on every note")).join(""),2,`data-set="port"`)
  +dkGroup("Legato",["amp","flt","lfo"].map(k=>dkk(`data-leg="${k}"`,tr.leg[k],k.toUpperCase(),`On: the ${k.toUpperCase()} envelope still fires when notes overlap`)).join(""),3)}
 return dkGroup("Channel",Array.from({length:16},(_,k)=>dkk(`data-v="${k+1}"`,tr.ch===k+1,k+1,"MIDI channel "+(k+1))).join(""),8,`data-set="mch"`)
  +`<div class="dkg"><span class="dkl">LFOs</span><span class="dkna">shared with T${t-5} ${S.tracks[t-6].m}</span></div>`}
/* the header: a readout and one help line */
function dockRead(t,d){const tr=trk(t);
 if(d==="arp")return`<span id="arpcap">Rhythm + offset · ${tr.arp.len} steps</span>`;
 if(d==="trn"){const n=tr.tr.TRACK-64+(tr.tr.SCALE===1?0:S.patTrn-64);return`plays ${n>0?"+":""}${n} semitones${tr.tr.SCALE===1?" · FIX: pattern ignored":""}`}
 if(d==="trig"){const a=ampSteps(t);return a===Infinity?"the gate sustains":`a gate sounds ≈ ${a<10?a.toFixed(1):Math.round(a)} steps`}
 return"CH "+String(tr.ch).padStart(2,"0")}
