const KIT_F=["m","name","v","lev","out","inp","trigpos","port","leg","assign"],MIDI_KIT_F=["v","cc","ch","name"],SEQ_F=["steps","slide","swing","arp","tr"];
const isSet=x=>x instanceof Set,isMap=x=>x instanceof Map;
